/* This command was used once to create the cache files, then 
    commented out for the actually load testing */

/*    web_dump_cache("paycheckcache",
        "FileName=c:\\temp\\{VuserName}paycheck", 
        "Replace=yes", LAST );		*/

// Get the previously created cache

web_load_cache("ActionLoad",
    "FileName=c:\\temp\\{VuserName}paycheck",
    LAST );

// Disables decoding
web_set_option("DecodeContent", "No", LAST );

// Enables decoding
web_set_option("DecodeContent", "Yes", LAST );

// Disables redirection. If redirection is required in following action functions, a warning is issued.
web_set_option("MaxRedirectionDepth", "0", LAST );

// Sets the maximum redirection depth to 10.
web_set_option("MaxRedirectionDepth", "10", LAST );

/* Use RC4-MD5 cipher for SSL */
web_set_sockets_option("SSL_CIPHER_LIST", "RC4-MD5");

/* Prevent downloading of images from unwanted_server */
web_set_sockets_option("DISALLOW_HOSTS",
    "a372.g.unwanted_server.net;a372.g.unwanted_server.net"); 

/* Sets the client's preferred IP address */
web_set_sockets_option("USER_IP_ADDRESS", "200.100.100.100");

// Turn on pre-emptive authentication for web server. The pre-emptive authenticate scheme is always "BASIC".
web_set_sockets_option("INITIAL_AUTH","BASIC");

// Turn off pre-emptive authentication for web server.
web_set_sockets_option("INITIAL_AUTH","NONE");

// Do the same for proxy server.
web_set_sockets_option("PROXY_INITIAL_AUTH","BASIC");
